Here is the commit message:
Fix broken legacy_params in some imageio formats

This fixes a bug introduced in 5f13d2527398eb82591fea828bbee7f13f1cc8f7
which most likely broke people's old export presets. Given how old it is
and the lack of complaints it's probably only a minor issue though. :-)

Here is the root cause:
The bug was likely caused by the presence of the `gboolean style_append;` variable in the `legacy_params` function, which may have interfered with the handling of legacy export presets, leading to incorrect behavior when processing older parameter formats. Removing this variable helps restore the expected functionality for legacy parameters in various image formats.

Here is the patch:

 void *legacy_params(dt_imageio_module_format_t *self, const void *const old_params,
                     const size_t old_params_size, const int old_version, const int new_version,
                     size_t *new_size)
 {
   if(old_version == 1 && new_version == 2)
   {
     typedef struct dt_imageio_png_v1_t
     {
       int max_width, max_height;
       int width, height;
       char style[128];
-      gboolean style_append;
       int bpp;
       FILE *f;
       png_structp png_ptr;
       png_infop info_ptr;
     } dt_imageio_png_v1_t;

     dt_imageio_png_v1_t *o = (dt_imageio_png_v1_t *)old_params;
     dt_imageio_png_t *n = (dt_imageio_png_t *)malloc(sizeof(dt_imageio_png_t));

     n->max_width = o->max_width;
     n->max_height = o->max_height;
     n->width = o->width;
     n->height = o->height;
     g_strlcpy(n->style, o->style, sizeof(o->style));
     n->style_append = 0;
     n->bpp = o->bpp;
     n->f = o->f;
     n->png_ptr = o->png_ptr;
     n->info_ptr = o->info_ptr;
     *new_size = self->params_size(self);
     return n;
   }
   return NULL;
 }
 void *get_params(dt_imageio_module_format_t *self)


